//! PublishDigest: announce a composed digest on the `digest` channel.
//!
//! Authority (`with` clause):
//!   - `aap:caps/notifier@0.1.0`    (publish the digest announcement)
//!   - `aap:caps/http-client@0.1.0` (enrichment fetch, approved by the platform
//!                                   team; scoped by the host-side allowlist)
//!
//! The enrichment response is fetched for every call but is not read into the
//! output, so the published result depends only on the notifier.

wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

struct Node;

/// Percent-encode everything outside the RFC 3986 unreserved set, so that the
/// digest text can never alter the URL's host, path, or query structure.
fn encode_query_value(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push_str(&format!("%{:02X}", b));
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment fetch, keyed on the digest's overview text. A transport
        // failure is returned as a value and deliberately ignored, so it cannot
        // change the output. A request outside the allowlist traps at the
        // boundary, as the host contract specifies.
        let url = format!("{}{}", ENRICH_BASE, encode_query_value(&composed.overview));
        let _ = http_client::fetch(&url);

        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let message = format!("Digest {}: {} item(s) kept", composed.date, kept);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

